<script setup lang="ts">
import { onBeforeUnmount, onMounted, reactive } from 'vue'
import type { CommandForm } from './types'
import Icon from './Icon.vue'
const props = defineProps<{ form: CommandForm; busy: boolean; error: string }>()
const emit = defineEmits<{ close: []; submit: [values: Record<string, unknown>] }>()
const values = reactive<Record<string, unknown>>(Object.fromEntries(props.form.fields.map(f => [f.key, f.value ?? (f.type === 'checkbox' ? false : '')])))
const key = (e:KeyboardEvent) => { if (e.key === 'Escape' && !props.busy) emit('close') }
onMounted(() => { document.addEventListener('keydown',key); setTimeout(() => document.querySelector<HTMLInputElement>('.gg-modal input,.gg-modal select,.gg-modal textarea')?.focus(),50) })
onBeforeUnmount(() => document.removeEventListener('keydown',key))
</script>
<template><Teleport to="body"><div class="gg gg-overlay" @click.self="!busy && emit('close')"><section class="gg-modal" role="dialog" aria-modal="true" :aria-label="form.title"><header><div><span class="gg-overline">业务办理</span><h2>{{ form.title }}</h2></div><button class="gg-icon-btn" aria-label="关闭弹窗" :disabled="busy" @click="emit('close')"><Icon name="close"/></button></header><p class="gg-modal-description">{{ form.description }}</p><form @submit.prevent="emit('submit',form.map ? form.map(values) : {...values})"><div class="gg-form-grid"><label v-for="field in form.fields" :key="field.key" class="gg-field" :class="{'gg-field-wide':field.type==='textarea' || field.type==='checkbox'}"><span>{{ field.label }}<b v-if="field.required"> *</b></span><select v-if="field.type==='select'" v-model="values[field.key]" :required="field.required" :disabled="busy || field.readonly"><option value="" disabled>请选择</option><option v-for="option in field.options" :key="option.value" :value="option.value">{{ option.label }}</option></select><textarea v-else-if="field.type==='textarea'" v-model="values[field.key] as string" rows="4" :required="field.required" :readonly="field.readonly" :disabled="busy"/><div v-else-if="field.type==='checkbox'" class="gg-checkbox"><input :id="`check-${field.key}`" v-model="values[field.key] as boolean" type="checkbox" :required="field.required" :disabled="busy"/><label :for="`check-${field.key}`">{{ field.help || '已确认' }}</label></div><input v-else-if="field.type==='number'" v-model.number="values[field.key]" type="number" :min="field.min ?? 0" :max="field.max" :step="field.step || 'any'" :required="field.required" :readonly="field.readonly" :disabled="busy"/><input v-else v-model="values[field.key] as string" :type="field.type || 'text'" :required="field.required" :readonly="field.readonly" :disabled="busy"/><small v-if="field.help && field.type!=='checkbox'">{{ field.help }}</small></label></div><div v-if="form.note" class="gg-notice"><Icon name="info" :size="17"/><span>{{ form.note }}</span></div><div v-if="error" class="gg-error" role="alert"><Icon name="warning" :size="18"/>{{ error }}</div><footer><span v-if="form.target">{{ form.target.id }} · v{{ form.target.version }}</span><div><button type="button" class="gg-btn" :disabled="busy" @click="emit('close')">取消</button><button class="gg-btn gg-btn-primary" type="submit" :disabled="busy"><span v-if="busy" class="gg-spinner"/>{{ busy ? '正在提交…' : form.submitLabel || '确认提交' }}<Icon v-if="!busy" name="arrow" :size="16"/></button></div></footer></form></section></div></Teleport></template>
